 assert(source.endsWith("-53"));assert(v[0]>=0&&v[0]<3);assert.equal(b.prompt.length,3);const[stem,premise,t]=b.prompt;assert(stem.type==="paragraph"&&premise.type==="paragraph"&&t.type==="table");assert.match(stem.text,/1人/);assert.match(stem.text,/6月1日/);assert.match(stem.text,/6月11日の終了時点/);assert.match(stem.text,/土曜日と日曜日を除く週5日間/);assert(!/2018|平成30|切り捨|切捨|四捨五入|丸め/.test(stem.text));assert.equal(premise.text,"表の順に作業を進め、コーディングより前の作業は完了し、その後の作業には着手していないものとする。");assert.deepEqual(t.columns,["作業","計画作業量（人日）","完了予定日"]);assert.deepEqual(t.rows,[["仕様書作成","2","6月2日（火）"],["プログラム設計","5","6月9日（火）"],["テスト計画書作成","1","6月10日（水）"],["コーディング","4","6月16日（火）"],["コンパイル","2","6月18日（木）"],["テスト","3","6月23日（火）"]]);const percent=Number(stem.text.match(/コーディング作業の(\d+)%/)?.[1]);assert.equal(percent,[25,50,75][v[0]]);const weights=t.rows.map(r=>Number(r[1])),total=weights.reduce((a,c)=>a+c,0),done=weights.slice(0,3).reduce((a,c)=>a+c,0)+weights[3]*percent/100,remaining=total-done,numerator=remaining*100;assert.equal(total,17);assert.equal(done,9+v[0]);assert.equal(remaining,8-v[0]);const row=facts.progress.cases[v[0]];assert.deepEqual(texts,row.choices.map(String));const distances=texts.map(s=>Math.abs(Number(s)*total-numerator)),minimum=Math.min(...distances);assert(minimum<total/2);const truth=distances.map(n=>n===minimum);assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));assert.equal(Math.floor(numerator/total),Number(texts[b.correctIndex!]));assert.equal(Math.round(numerator/total),Number(texts[b.correctIndex!]));assert(!texts.includes(String(Math.ceil(numerator/total))));assert.match(b.explanation,new RegExp(`残りは17−${done}=${remaining}人日`));return{truth,answer:texts[b.correctIndex!],model:"independent exact fraction and candidate distances",total,done,remaining,numerator,denominator:total};
